import React from "react";
import Typewriter from "typewriter-effect";
import { greeting } from "../../portfolio";

function Type() {
  return (
    <Typewriter
      options={{
        // The role line reads as a title, so the trailing emoji in the shared
        // strings are dropped here (other pages still use them as written).
        strings: greeting.subTitle.map((t) =>
          t.replace(/[^\x20-\x7E]+$/u, "").trim()
        ),
        autoStart: true,
        loop: true,
        deleteSpeed: 50,
        // The library splits with String.prototype.split(""), which cuts the
        // 🤖 / 💻 surrogate pairs in half and renders a � for one frame on
        // the way in and on the way out. Array.from is code-point aware.
        stringSplitter: (s) => Array.from(s),
      }}
    />
  );
}

export default Type;
