    <path d="M7.500 5.500H4.800A1.300 1.300 0 0 0 3.500 6.800c0 2.200 1.700 3.900 4.200 4M16.500 5.500h2.700a1.300 1.300 0 0 1 1.300 1.300c0 2.200-1.700 3.900-4.200 4" />
